import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { ApiConfig } from 'lib/api'
import { supportLogic } from 'lib/components/Support/supportLogic'

import { oauthApplicationsList } from '~/generated/core/api'
import { OrganizationOAuthApplicationApi } from '~/generated/core/api.schemas'

import { reviewSupportMessage, verificationRequestMessage } from './oauthAppSupportMessages'

export type OAuthAppSupportRequest = 'review' | 'verification'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface oauthAppsLogicValues {
    oauthApps: OrganizationOAuthApplicationApi[] | null
    oauthAppsLoadFailed: boolean
    oauthAppsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface oauthAppsLogicActions {
    contactSupport: (
        app: OrganizationOAuthApplicationApi,
        request: OAuthAppSupportRequest
    ) => {
        app: OrganizationOAuthApplicationApi
        request: OAuthAppSupportRequest
    }
    loadOAuthApps: () => any
    loadOAuthAppsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadOAuthAppsSuccess: (
        oauthApps: OrganizationOAuthApplicationApi[],
        payload?: any
    ) => {
        oauthApps: OrganizationOAuthApplicationApi[]
        payload?: any
    }
}

export type oauthAppsLogicType = MakeLogicType<oauthAppsLogicValues, oauthAppsLogicActions>

export const oauthAppsLogic = kea<oauthAppsLogicType>([
    path(['scenes', 'settings', 'organization', 'oauthAppsLogic']),

    actions({
        contactSupport: (app: OrganizationOAuthApplicationApi, request: OAuthAppSupportRequest) => ({ app, request }),
    }),

    loaders(() => ({
        oauthApps: [
            null as OrganizationOAuthApplicationApi[] | null,
            {
                loadOAuthApps: async () => {
                    const response = await oauthApplicationsList(ApiConfig.getCurrentOrganizationId())
                    return response.results
                },
            },
        ],
    })),

    reducers({
        oauthAppsLoadFailed: [
            false,
            {
                loadOAuthApps: () => false,
                loadOAuthAppsSuccess: () => false,
                loadOAuthAppsFailure: () => true,
            },
        ],
    }),

    listeners(() => ({
        contactSupport: ({ app, request }) => {
            // pinned: analytics event name and properties
            posthog.capture('oauth app support requested', {
                request,
                provisioning_status: app.provisioning_status,
                review_status: app.provisioning_review?.status ?? null,
                is_verified: app.is_verified ?? false,
            })
            supportLogic.actions.openSupportForm({
                kind: 'support',
                isEmailFormOpen: true,
                oauth_app_request: true,
                message: request === 'review' ? reviewSupportMessage(app) : verificationRequestMessage(app),
            })
        },
    })),

    afterMount(({ actions }) => {
        actions.loadOAuthApps()
    }),
])
